    const float* __restrict__ x,
    const float* __restrict__ add_value,
    float* __restrict__ out,
    int M,
    int N
) {
    __shared__ float s_add_value[TILE_N];

    const int tid = threadIdx.x;
    const int threads = blockDim.x;
    const int block_col_start = blockIdx.x * TILE_N;

    if (block_col_start >= N) return;

    const int tile_cols = min(TILE_N, N - block_col_start);

    for (int i = tid; i < tile_cols; i += threads) {
        s_add_value[i] = add_value[block_col_start + i];
    }
    __syncthreads();

    const int row = blockIdx.y;
    if (row >= M) return;

    const int base_idx = row * N + block_col_start;

    for (int col = tid; col < tile_cols; col += threads) {
        const int idx = base_idx + col;
        float v = x[idx] + s_add_value[col];

        float sig = 1.0f / (1.0f + __expf(-v));
        v = v * sig;

