    v = v * (1.0f / (1.0f + __expf(-v)));
    v = tanhf(v);
    { float c = v * v * v; v = 0.5f * v * (1.0f + tanhf(0.7978845608028654f * (v + 0.044715f * c))); }
    res.w = fmaxf(-1.0f, fminf(1.0f, v));

